// Package slogutil installs and configures the activity service's structured
// logging. Logs go to stdout: a coloured human-friendly format when stdout is
// a terminal, JSON otherwise (for ingestion by the fleet's log pipeline).
//
// The context handler correlates logs with traces — it injects trace_id and
// span_id from the active span and surfaces OTel baggage members as
// attributes, so a log line emitted inside a span can be jumped to its trace.
// Ported from entiredb/slogutil to match the fleet standard.
package slogutil

import (
	"context"
	"log/slog"
	"os"
	"strings"

	"github.com/lmittmann/tint"
	"github.com/mattn/go-isatty"
)

// NewStdoutHandler returns a slog.Handler writing to stdout. When stdout is a
// terminal, lines render in a coloured format via tint with a time-only
// timestamp and the service name immediately after the level (e.g.
// `12:03:53.495 INF repo-activity starting`). Otherwise JSON is emitted with
// service carried as a structured attribute.
func NewStdoutHandler(service string, level slog.Level) slog.Handler {
	return newHandler(os.Stdout, service, level)
}

// NewStderrHandler is NewStdoutHandler's stderr twin -- for a one-shot CLI
// command (cmd/runner's `launch`) that also prints a machine-readable result
// line to stdout: put logs on stderr instead, so `| grep run_id=` isn't
// relying on the log handler's own format (JSON never collides, but tint's
// terminal `key=value` rendering can) to keep the two apart.
func NewStderrHandler(service string, level slog.Level) slog.Handler {
	return newHandler(os.Stderr, service, level)
}

func newHandler(w *os.File, service string, level slog.Level) slog.Handler {
	if isatty.IsTerminal(w.Fd()) {
		h := tint.NewHandler(w, &tint.Options{
			Level:      level,
			TimeFormat: "15:04:05.000",
		})
		if service == "" {
			return h
		}
		return servicePrefixHandler{Handler: h, prefix: service}
	}
	h := slog.Handler(slog.NewJSONHandler(w, &slog.HandlerOptions{Level: level}))
	if service != "" {
		h = h.WithAttrs([]slog.Attr{slog.String("service", service)})
	}
	return h
}

// Install sets the stdout handler (wrapped in the trace-correlating context
// handler) as slog's default logger. Safe to call more than once — the last
// call wins. Each binary calls this once at startup with its service name.
func Install(service string, level slog.Level) {
	slog.SetDefault(slog.New(NewCtxHandler(NewStdoutHandler(service, level))))
}

// LevelFromEnv reads LOG_LEVEL (debug|info|warn|error, case-insensitive),
// defaulting to Info. Lets a deployment dial up verbosity without a rebuild.
func LevelFromEnv() slog.Level {
	switch strings.ToLower(os.Getenv("LOG_LEVEL")) {
	case "debug":
		return slog.LevelDebug
	case "warn", "warning":
		return slog.LevelWarn
	case "error":
		return slog.LevelError
	default:
		return slog.LevelInfo
	}
}

// servicePrefixHandler prepends a fixed service token to every record's
// message so tint renders it immediately after the level. JSON output keeps
// service as a structured attribute instead (see NewStdoutHandler).
type servicePrefixHandler struct {
	slog.Handler

	prefix string
}

func (h servicePrefixHandler) Handle(ctx context.Context, r slog.Record) error {
	r.Message = h.prefix + " " + r.Message
	return h.Handler.Handle(ctx, r) //nolint:wrapcheck // pass-through
}

func (h servicePrefixHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	return servicePrefixHandler{Handler: h.Handler.WithAttrs(attrs), prefix: h.prefix}
}

func (h servicePrefixHandler) WithGroup(name string) slog.Handler {
	return servicePrefixHandler{Handler: h.Handler.WithGroup(name), prefix: h.prefix}
}

