func main() {
	// Subcommand dispatch. `meta-fanout backfill ...` / `backfill-prs ...`
	// enqueue one-shot backfill jobs (github_meta / open-PR respectively) and
	// exit; no subcommand runs the long-lived worker (the default the fleet
	// deployment invokes, so its argv is unchanged).
	if len(os.Args) > 1 && os.Args[1] == "backfill" {
		if err := runBackfill(os.Args[2:]); err != nil {
			slog.Error("backfill failed", slog.Any("error", err))
			os.Exit(1)
		}
		return
	}
	if len(os.Args) > 1 && os.Args[1] == "backfill-prs" {
		if err := runBackfillPRs(os.Args[2:]); err != nil {
			slog.Error("backfill-prs failed", slog.Any("error", err))
			os.Exit(1)
		}
		return
	}
	if err := run(); err != nil {
		slog.Error("meta-fanout failed", slog.Any("error", err))
		os.Exit(1)
	}
}
