// Package donejobs defines the mirror-completion event contract published
// to the per-cell repo_ops_v1 stream when a mirror sync reaches a terminal
// state. Completion is a new op (mirror_done) on the generic repo-ops bus
// rather than its own stream — the op token in repo.ops.v1.<jur>.<cluster>.<op>
// is designed to host exactly this without proliferating streams.
//
// The mirror worker publishes one Job into its cell-local NATS island on
// the subject repo.ops.v1.<jurisdiction>.<cluster>.mirror_done whenever a
// sync_repo job settles terminally: StatusReady on a successful (or benignly
// empty) clone, StatusFailed on a permanent failure or one that exhausted
// redeliveries. The co-located regional entire-core binds the in-cell
// repo_ops_v1 (filtered to the mirror_done op) and flips mirror_repos.status
// (processing → ready|failed), which the CLI polls instead of probing the
// data plane with a clone.
//
// SOURCE OF TRUTH for the wire shape is shared with the consumer:
// entiredb internal/entirecore/mirrordone.event. The two are separate Go
// modules, so the contract is DUPLICATED rather than imported — exactly as
// pkg/gitjobs is duplicated by entiredb core/mirrorrepo/gitjobs. Any field
// added/renamed is a contract change that lands on both sides; bump
// Version1 and keep old fields readable across a rollout.
//
// Modeled on pkg/gitjobs (placement-scoped subject) and pkg/metajobs.
package donejobs

import (
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"

	"go.opentelemetry.io/otel/attribute"
)

const (
	// StreamName is the generic per-cell repo-ops JetStream that carries the
	// mirror_done op. Provisioned declaratively in fleet (apps/nats-streams) —
	// this producer neither creates nor reconciles it, only publishes to it.
	StreamName = "repo_ops_v1"

	// SubjectPrefix + Op compose the placement-scoped wire subject. Full wire
	// form: repo.ops.v1.<jurisdiction>.<cluster>.mirror_done — the op token
	// distinguishes completions from other repo ops (e.g. teardown) on the same
	// bus. jurisdiction + cluster are low-cardinality and routing-relevant; the
	// repo identity is carried in the payload (Job.RepoULID), not the subject.
	SubjectPrefix = "repo.ops.v1."
	// Op is the repo-ops operation token for a mirror completion.
	Op = "mirror_done"

	// Version1 is stamped into Job.Version so the consumer can handle a
	// mixed-version rollout.
	Version1 = 1
)

// Status is the terminal disposition of a mirror sync as seen by entire-core.
// It deliberately collapses the worker's richer disposition set: a benign
// empty-source no-op and a ref-applying success both read as ready (the
// mirror is clonable), while a permanent failure and a redelivery-exhausted
// transient both read as failed (the initial clone did not land).
type Status string

const (
	// StatusReady means the mirror is clonable: a sync applied refs, or the
	// upstream was empty (an empty repo is still clonable).
	StatusReady Status = "ready"
	// StatusFailed means the initial clone did not land — a permanent error
	// (repo gone, validation reject) or one that exhausted redeliveries.
	StatusFailed Status = "failed"
)

// Subject returns the placement-scoped wire subject for a (jurisdiction,
// cluster): repo.ops.v1.<jurisdiction>.<cluster>.mirror_done. The worker
// composes it from its own placement; the regional consumer filters on
// repo.ops.v1.<jurisdiction>.*.mirror_done to span every cluster in its
// jurisdiction without picking up other repo ops.
func Subject(jurisdiction, cluster string) string {
	return SubjectPrefix + jurisdiction + "." + cluster + "." + Op
}

// Job is the canonical mirror-completion wire payload (repo_ops_v1, mirror_done op).
type Job struct {
	// Version lets the consumer handle a mixed-version rollout.
	Version int `json:"version"`

	// RepoULID is the placement's repo identity — the same per-placement
	// target ULID git-sync routes on (gitjobs.Target.ULID) and the primary
	// key of entire-core's mirror_repos row. It is the only field the
	// consumer needs to flip the status. Always present.
	RepoULID string `json:"repo_ulid"`

	// Status is the terminal disposition (ready|failed).
	Status Status `json:"status"`
}

// MsgID builds the Nats-Msg-Id dedup key. (repo_ulid, status) is stable
// across worker redeliveries of the same terminal outcome, so idempotent
// republishes collapse within the stream's duplicate window. The consumer's
// status write is itself idempotent, so this is an optimisation, not a
// correctness dependency.
func MsgID(repoULID string, status Status) string {
	return repoULID + "/" + string(status)
}

func (j Job) withVersion() Job {
	if j.Version == 0 {
		j.Version = Version1
	}
	return j
}

// Validate checks the fields the consumer's correctness depends on: a
// non-empty RepoULID (its primary key) and a known terminal Status.
func (j Job) Validate() error {
	if j.RepoULID == "" {
		return errors.New("repo_ulid is required")
	}
	switch j.Status {
	case StatusReady, StatusFailed:
	default:
		return fmt.Errorf("unknown status %q", j.Status)
	}
	return nil
}

func (j Job) validateVersion(allowZero bool) error {
	if allowZero && j.Version == 0 {
		return nil
	}
	if j.Version != Version1 {
		return fmt.Errorf("unknown version %d", j.Version)
	}
	return nil
}

// Marshal stamps Version1 if unset, validates, and serializes to the wire
// JSON the consumer decodes.
func Marshal(j Job) ([]byte, error) {
	j = j.withVersion()
	if err := j.Validate(); err != nil {
		return nil, err
	}
	data, err := json.Marshal(j)
	if err != nil {
		return nil, fmt.Errorf("marshal done job: %w", err)
	}
	return data, nil
}

// Unmarshal is the inverse of Marshal, with version + field validation.
func Unmarshal(data []byte) (Job, error) {
	var j Job
	if err := json.Unmarshal(data, &j); err != nil {
		return j, fmt.Errorf("unmarshal done job: %w", err)
	}
	if err := j.validateVersion(false); err != nil {
		return j, fmt.Errorf("validate done job: %w", err)
	}
	if err := j.Validate(); err != nil {
		return j, fmt.Errorf("validate done job: %w", err)
	}
	return j, nil
}

// SpanAttrs returns OTel span attributes identifying the job (placement is
// added at the publish site from the subject tokens).
func (j Job) SpanAttrs() []attribute.KeyValue {
	return []attribute.KeyValue{
		attribute.String("entire.target_ulid", j.RepoULID),
		attribute.String("entire.mirror.status", string(j.Status)),
	}
}

// LogAttrs is the slog counterpart to SpanAttrs (without the "entire." prefix).
func (j Job) LogAttrs() []slog.Attr {
	return []slog.Attr{
		slog.String("target_ulid", j.RepoULID),
		slog.String("status", string(j.Status)),
	}
}

package main

import (
	"bufio"
	"context"
	"errors"
	"flag"
	"fmt"
	"log/slog"
	"os"
	"strconv"
	"strings"
	"time"
)

// tsvHeader is shared by list-failed (writer) and redeliver (reader) so the
// two commands compose: pipe one into a file, feed it to the other.
const tsvHeader = "id\tguid\tdelivered_at\tevent\taction\tstatus_code\tstatus\trepository_id\tredelivery"

func runWebhooks(ctx context.Context, args []string) error {
	if len(args) == 0 {
		return errors.New("usage: mirror-pipeline-admin webhooks <list-failed|redeliver|dlq>")
	}
	switch args[0] {
	case "list-failed":
		return runWebhooksListFailed(ctx, args[1:])
	case "redeliver":
		return runWebhooksRedeliver(ctx, args[1:])
	case "dlq":
		return runWebhooksDLQ(ctx, args[1:])
	default:
		return fmt.Errorf("unknown webhooks command %q (want list-failed, redeliver or dlq)", args[0])
	}
}

// authFlags registers the shared GitHub App credential flags on fs.
func authFlags(fs *flag.FlagSet) (appID, keyPath *string) {
	appID = fs.String("app-id", os.Getenv("ENTIRE_GITHUB_APP_ID"),
		"GitHub App id or client id (env ENTIRE_GITHUB_APP_ID)")
	keyPath = fs.String("private-key", os.Getenv("ENTIRE_GITHUB_APP_PRIVATE_KEY_FILE"),
		"path to the App private-key PEM (env ENTIRE_GITHUB_APP_PRIVATE_KEY_FILE)")
	return appID, keyPath
}

func clientFromFlags(ctx context.Context, appID, keyPath string) (*appClient, error) {
	if keyPath == "" {
		return nil, errors.New("private key is required (--private-key or ENTIRE_GITHUB_APP_PRIVATE_KEY_FILE)")
	}
	pemBytes, err := os.ReadFile(keyPath)
	if err != nil {
		return nil, fmt.Errorf("read private key: %w", err)
	}
	client, err := newAppClient(appID, pemBytes)
	if err != nil {
		return nil, err
	}
	who, err := client.whoami(ctx) // fail fast on bad creds, and log identity
	if err != nil {
		return nil, fmt.Errorf("authenticate as app: %w", err)
	}
	slog.Info("authenticated", slog.String("app_slug", who.Slug), slog.Int64("app_id", who.ID))
	return client, nil
}

// parseWithOnePositional parses flags that may appear before OR after a single
// positional argument. Go's flag stops at the first non-flag token, so a plain
// Parse would silently drop flags written after the file path; this resumes
// parsing past the positional. Returns flag.ErrHelp verbatim so callers can
// exit 0 on -h.
func parseWithOnePositional(fs *flag.FlagSet, args []string) (string, error) {
	var pos string
	rest := args
	for {
		if err := fs.Parse(rest); err != nil {
			return "", err // includes flag.ErrHelp
		}
		rest = fs.Args()
		if len(rest) == 0 {
			return pos, nil
		}
		if pos != "" {
			return "", fmt.Errorf("unexpected extra argument %q", rest[0])
		}
		pos, rest = rest[0], rest[1:]
	}
}

func runWebhooksListFailed(ctx context.Context, args []string) error {
	fs := flag.NewFlagSet("webhooks list-failed", flag.ContinueOnError)
	appID, keyPath := authFlags(fs)
	sinceStr := fs.String("since", "", "only deliveries at/after this RFC3339 time, e.g. 2026-05-27T08:00:00Z (required)")
	untilStr := fs.String("until", "", "only deliveries at/before this RFC3339 time (optional; default: now)")
	outPath := fs.String("out", "", "write the TSV here (default: stdout)")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil // -h: usage already printed
		}
		return err
	}
	if *sinceStr == "" {
		return errors.New("--since is required")
	}
	since, err := time.Parse(time.RFC3339, *sinceStr)
	if err != nil {
		return fmt.Errorf("--since: %w", err)
	}
	var until time.Time
	if *untilStr != "" {
		if until, err = time.Parse(time.RFC3339, *untilStr); err != nil {
			return fmt.Errorf("--until: %w", err)
		}
	}

	client, err := clientFromFlags(ctx, *appID, *keyPath)
	if err != nil {
		return err
	}

	out := os.Stdout
	if *outPath != "" {
		f, err := os.Create(*outPath)
		if err != nil {
			return err
		}
		defer func() { _ = f.Close() }()
		out = f
	}

	slog.Info("listing failed deliveries", slog.Time("since", since))
	failed, scanned, err := client.listFailed(ctx, since, until)
	if err != nil {
		return err
	}

	_, _ = fmt.Fprintln(out, tsvHeader)
	for _, d := range failed {
		_, _ = fmt.Fprintf(out, "%d\t%s\t%s\t%s\t%s\t%d\t%s\t%d\t%t\n",
			d.ID, d.GUID, d.DeliveredAt.Format(time.RFC3339Nano), d.Event, d.Action,
			d.StatusCode, d.Status, d.RepositoryID, d.Redelivery)
	}
	slog.Info("done", slog.Int("scanned", scanned), slog.Int("failed", len(failed)))
	return nil
}

type target struct {
	id    int64
	event string
}

func runWebhooksRedeliver(ctx context.Context, args []string) error {
	fs := flag.NewFlagSet("webhooks redeliver", flag.ContinueOnError)
	appID, keyPath := authFlags(fs)
	live := fs.Bool("live", false, "actually POST redeliveries (default: dry-run, prints a sample and exits)")
	rate := fs.Float64("rate", 3, "target redeliveries/sec; GitHub's write ceiling is ~3/s")
	eventsCSV := fs.String("events", "", "only these comma-separated X-GitHub-Event types (default: all)")
	donePath := fs.String("done", "redeliver-done.log", "progress log; 2xx ids here are skipped on re-run (failures are retried)")
	file, err := parseWithOnePositional(fs, args)
	if errors.Is(err, flag.ErrHelp) {
		return nil
	}
	if err != nil {
		return err
	}
	if file == "" {
		return errors.New("usage: mirror-pipeline-admin webhooks redeliver <failed.tsv> [flags]")
	}

	eventFilter := map[string]bool{}
	for _, e := range strings.Split(*eventsCSV, ",") {
		if e = strings.TrimSpace(e); e != "" {
			eventFilter[e] = true
		}
	}

	done, err := loadDone(*donePath)
	if err != nil {
		return err
	}
	work, err := loadTargets(file, eventFilter, done)
	if err != nil {
		return err
	}

	mode := "DRY-RUN"
	if *live {
		mode = "LIVE"
	}
	slog.Info("redelivery plan",
		slog.Int("targets", len(work)), slog.Int("already_done", len(done)),
		slog.Float64("rate", *rate), slog.String("mode", mode))

	if !*live {
		for i, w := range work {
			if i >= 10 {
				break
			}
			fmt.Printf("would POST /app/hook/deliveries/%d/attempts  (%s)\n", w.id, w.event)
		}
		slog.Info("dry-run only; re-run with --live to redeliver", slog.Int("of", len(work)))
		return nil
	}

	client, err := clientFromFlags(ctx, *appID, *keyPath)
	if err != nil {
		return err
	}

	logf, err := os.OpenFile(*donePath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	defer func() { _ = logf.Close() }()

	var interval time.Duration
	if *rate > 0 {
		interval = time.Duration(float64(time.Second) / *rate)
	}

	start := time.Now()
	var ok, failed int
	for i, w := range work {
		t0 := time.Now()
		status, body, err := client.redeliver(ctx, w.id)
		if err != nil {
			if ctx.Err() != nil {
				slog.Warn("interrupted; resume by re-running the same command", slog.Int("completed", i))
				return ctx.Err()
			}
			failed++
			_, _ = fmt.Fprintf(logf, "%d\t0\t%s\n", w.id, w.event)
			slog.Warn("redeliver error", slog.Int64("id", w.id), slog.Any("error", err))
		} else {
			_, _ = fmt.Fprintf(logf, "%d\t%d\t%s\n", w.id, status, w.event)
			if status >= 200 && status < 300 {
				ok++
			} else {
				failed++
				slog.Warn("redeliver non-2xx", slog.Int64("id", w.id), slog.Int("status", status), slog.String("body", body))
			}
		}
		if (i+1)%100 == 0 {
			eff := float64(i+1) / time.Since(start).Seconds()
			slog.Info("progress", slog.Int("done", i+1), slog.Int("of", len(work)),
				slog.Int("ok", ok), slog.Int("err", failed), slog.String("rate", fmt.Sprintf("%.1f/s", eff)))
		}
		if d := interval - time.Since(t0); d > 0 {
			select {
			case <-ctx.Done():
				slog.Warn("interrupted; resume by re-running the same command", slog.Int("completed", i+1))
				return ctx.Err()
			case <-time.After(d):
			}
		}
	}
	slog.Info("finished", slog.Int("ok", ok), slog.Int("err", failed))
	return nil
}

// loadDone returns the set of delivery ids already redelivered with a 2xx, so a
// re-run skips them. Non-2xx rows are intentionally excluded (retry on re-run).
func loadDone(path string) (map[int64]bool, error) {
	done := map[int64]bool{}
	f, err := os.Open(path)
	if errors.Is(err, os.ErrNotExist) {
		return done, nil
	}
	if err != nil {
		return nil, err
	}
	defer func() { _ = f.Close() }()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		fields := strings.Split(sc.Text(), "\t")
		if len(fields) < 2 {
			continue
		}
		id, err := strconv.ParseInt(fields[0], 10, 64)
		if err != nil {
			continue
		}
		if code, err := strconv.Atoi(fields[1]); err == nil && code >= 200 && code < 300 {
			done[id] = true
		}
	}
	return done, sc.Err()
}

// loadTargets reads a list-failed TSV (id<TAB>guid<TAB>delivered_at<TAB>event…),
// applying the event filter and skipping ids already redelivered.
//
// list-failed pages GitHub newest-first, so the file is in reverse chronological
// order. The consumer's ordering guard is stamped at receipt, so replaying in
// file order lands PRs on their oldest state. We reverse into oldest-first here
// so redelivery moves forward in time.
func loadTargets(path string, eventFilter map[string]bool, done map[int64]bool) ([]target, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer func() { _ = f.Close() }()

	var work []target
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 1024*1024) // headroom for long rows
	first := true
	for sc.Scan() {
		line := sc.Text()
		if first {
			first = false
			if strings.HasPrefix(line, "id\t") { // tolerate the header row
				continue
			}
		}
		fields := strings.Split(line, "\t")
		if len(fields) < 4 {
			continue
		}
		id, err := strconv.ParseInt(fields[0], 10, 64)
		if err != nil {
			continue
		}
		event := fields[3]
		if len(eventFilter) > 0 && !eventFilter[event] {
			continue
		}
		if done[id] {
			continue
		}
		work = append(work, target{id: id, event: event})
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	for i, j := 0, len(work)-1; i < j; i, j = i+1, j-1 {
		work[i], work[j] = work[j], work[i]
	}
	return work, nil
}

