// Package natslog picks the severity a NATS pull-consumer failure warrants.
//
// The consumer loops in this repo already treat one such failure as routine:
// ErrStreamNotFound during a rollout is logged at warn "so operator alerts on
// ERROR aren't tripped by normal startup ordering" (cmd/worker/consumer.go).
// That reasoning generalises. A dropped link, a drained connection, a consumer
// that moved — the subscribe loop absorbs all of them by retrying with backoff,
// and none of them is something an operator can act on.
//
// Left at error level they are not merely untidy, they are load-bearing in the
// wrong direction: one mirror-pipeline pod emitted 57 ErrNoResponders inside 83
// milliseconds as its in-flight fetches failed together during a deploy, and
// two services between them tripped a cluster's error-log alert three times in
// forty minutes. Every one of those alerts was accurate about the count and
// wrong about the meaning, which is how a signal stops being read (COR-1228).
//
// Error stays reserved for failures the loop does not absorb.
package natslog

import (
	"log/slog"

	nuts "github.com/entireio/go-nuts"
)

// Err logs a subscribe or fetch failure at the severity its recoverability
// warrants: warn when the retry loop absorbs it, error otherwise.
//
// It deliberately does not decide control flow. Callers keep their existing
// return-and-resubscribe or continue-with-backoff behaviour; only the severity
// changes, so this cannot alter how the consumers recover.
func Err(msg string, err error) {
	if nuts.IsTransientFetchErr(err) {
		slog.Warn(msg, slog.Any("error", err))
		return
	}
	slog.Error(msg, slog.Any("error", err))
}

