package natslog

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"testing"

	"github.com/nats-io/nats.go"
)

// TestErrSeverity pins which failures are allowed to reach error level. The
// alerting that depends on this counts `status:error` log lines, so a change
// here silently changes what pages people — the reason each case names the
// error rather than testing the predicate generically.
func TestErrSeverity(t *testing.T) {
	tests := []struct {
		name string
		err  error
		want string
	}{
		// Absorbed by the subscribe/retry loop — the deploy and NATS-upgrade
		// bursts that were tripping the cluster error-log alert.
		{"no responders", nats.ErrNoResponders, "WARN"},
		{"fetch disconnected", nats.ErrFetchDisconnected, "WARN"},
		{"leadership changed", nats.ErrConsumerLeadershipChanged, "WARN"},
		{"consumer deleted", nats.ErrConsumerDeleted, "WARN"},
		{"connection draining", nats.ErrConnectionDraining, "WARN"},
		{"wrapped transient", fmt.Errorf("fetch: %w", nats.ErrConnectionClosed), "WARN"},

		// Not absorbed — these must stay loud.
		{"unknown failure", errors.New("boom"), "ERROR"},
		{"context deadline", context.DeadlineExceeded, "ERROR"},
		{"stream not found", nats.ErrStreamNotFound, "ERROR"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var buf bytes.Buffer
			prev := slog.Default()
			slog.SetDefault(slog.New(slog.NewJSONHandler(&buf, &slog.HandlerOptions{Level: slog.LevelDebug})))
			t.Cleanup(func() { slog.SetDefault(prev) })

			Err("Fetch error", tt.err)

			var rec map[string]any
			if err := json.Unmarshal(buf.Bytes(), &rec); err != nil {
				t.Fatalf("unmarshal log line: %v (%q)", err, buf.String())
			}
			if got := rec["level"]; got != tt.want {
				t.Errorf("level = %v, want %v", got, tt.want)
			}
			if got := rec["msg"]; got != "Fetch error" {
				t.Errorf("msg = %v, want the caller's message", got)
			}
		})
	}
}

// The severity is what Datadog indexes, so the emitted level name must be one
// the collector's `level` mapping understands. A level that arrives as anything
// else degrades the record to status:info — COR-1226's failure mode.
func TestErrEmitsRecognisedLevelNames(t *testing.T) {
	for _, err := range []error{nats.ErrNoResponders, errors.New("boom")} {
		var buf bytes.Buffer
		prev := slog.Default()
		slog.SetDefault(slog.New(slog.NewJSONHandler(&buf, nil)))
		Err("Fetch error", err)
		slog.SetDefault(prev)

		var rec map[string]any
		if uerr := json.Unmarshal(buf.Bytes(), &rec); uerr != nil {
			t.Fatalf("unmarshal: %v", uerr)
		}
		switch rec["level"] {
		case "WARN", "ERROR":
		default:
			t.Errorf("level = %v, want WARN or ERROR (the collector's preset names)", rec["level"])
		}
	}
}

