package natslog_test

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"testing"
)

// Subscribe and fetch failures route through natslog.Err, which picks the
// severity by recoverability. A bare slog.Error on one of those paths puts
// restart noise back into status:error and re-creates COR-1228.
//
// This exists because the convention was applied by hand and one path was
// missed: cmd/meta-fanout's lifecycle consumer kept a bare slog.Error on its
// PullSubscribe branch while its own fetch branch was migrated. The miss came
// from scoping the work off the log patterns Datadog happened to show — that
// consumer's subscribe failure had not fired in the sampled window, so it never
// appeared, and nothing else would have surfaced it. A reviewer caught it.
// Convention held only in someone's head is the same silent-hole problem the
// rest of this package is about, so it is checked here instead.
var subscribeOrFetchMsg = regexp.MustCompile(`(?i)(subscribe|fetch)`)

// errorLogArgIndex maps the slog error-level calls to the position of their
// message argument.
var errorLogArgIndex = map[string]int{
	"Error":        0,
	"ErrorContext": 1,
}

func TestSubscribeAndFetchFailuresUseNatslog(t *testing.T) {
	root := filepath.Join("..", "..")
	fset := token.NewFileSet()

	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			switch d.Name() {
			case "vendor", "gen", ".git", "node_modules":
				return filepath.SkipDir
			}
			return nil
		}
		// Test files may log whatever they like; natslog itself is the one
		// place a bare slog.Error on this path is correct.
		if !strings.HasSuffix(path, ".go") ||
			strings.HasSuffix(path, "_test.go") ||
			strings.Contains(filepath.ToSlash(path), "/internal/natslog/") {
			return nil
		}

		file, parseErr := parser.ParseFile(fset, path, nil, 0)
		if parseErr != nil {
			return nil
		}

		ast.Inspect(file, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			sel, ok := call.Fun.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			pkg, ok := sel.X.(*ast.Ident)
			if !ok || pkg.Name != "slog" {
				return true
			}
			idx, isErrorLog := errorLogArgIndex[sel.Sel.Name]
			if !isErrorLog || len(call.Args) <= idx {
				return true
			}
			lit, ok := call.Args[idx].(*ast.BasicLit)
			if !ok || lit.Kind != token.STRING {
				return true
			}
			msg, unquoteErr := strconv.Unquote(lit.Value)
			if unquoteErr != nil || !subscribeOrFetchMsg.MatchString(msg) {
				return true
			}
			t.Errorf("%s: slog.%s(%q, ...) — subscribe/fetch failures must go through natslog.Err "+
				"so a recoverable interruption is not logged at error level (COR-1228)",
				fset.Position(lit.Pos()), sel.Sel.Name, msg)
			return true
		})
		return nil
	})
	if err != nil {
		t.Fatalf("walk module: %v", err)
	}
}

